// before: sync-over-async, a deadlock in WPF
void OnClick(object s, RoutedEventArgs e)
{
    var data = GetDataAsync().Result;
    label.Text = data;
}

// after: async all the way
async void OnClick(object s, RoutedEventArgs e)
{
    var data = await GetDataAsync();
    label.Text = data;
}

